      "code": "(defparameter *rows* 6)\n(defparameter *cols* 7)\n(defparameter *empty-cell* #\\.)\n(defparameter *players* (vector #\\X #\\O))\n(defparameter *header* \"=== Connect Four ===\")\n(defparameter *rules* \"Get four of your pieces in a row to win. Columns are numbered 1-7.\")\n(defparameter *space-chars* (mapcar #'code-char '(9 10 11 12 13 32)))\n\n(defun make-board ()\n    (make-array (list *rows* *cols*) :initial-element *empty-cell*))\n\n(defun lowest-empty-row (board column)\n    (dotimes (row *rows* -1)\n        (when (char= (aref board row column) *empty-cell*)\n            (return row))))\n\n(defun run-matches (board player start-row start-column row-step column-step)\n    (dotimes (step 4)\n        (let ((row (+ start-row (* step row-step)))\n                (column (+ start-column (* step column-step))))\n            (when (or (< row 0) (>= row *rows*) (< column 0) (>= column *cols*))\n                (return-from run-matches nil))\n            (unless (char= (aref board row column) player)\n                (return-from run-matches nil))))\n    t)\n\n(defun has-four (board player)\n    (dotimes (row *rows*)\n        (dotimes (column *cols*)\n            (when (or (run-matches board player row column 0 1)\n                        (run-matches board player row column 1 0)\n                        (run-matches board player row column 1 1)\n                        (run-matches board player row column 1 -1))\n                (return-from has-four t))))\n    nil)\n\n(defun border ()\n    (concatenate 'string \"+\" (make-string (1- (* *cols* 2)) :initial-element #\\-) \"+\"))\n\n(defun print-board (board)\n    (format t \" ~{~a~^ ~}~%\" (loop for column from 1 to *cols* collect column))\n    (format t \"~a~%\" (border))\n    (loop for row from (1- *rows*) downto 0 do\n        (format t \"|~{~a~^ ~}|~%\"\n            (loop for column below *cols* collect (aref board row column))))\n    (format t \"~a~%\" (border))\n    (finish-output))\n\n(defun is-whole-number (text)\n    (let ((body\n            (if (and (> (length text) 0)\n                    (or (char= (char text 0) #\\+)\n                        (char= (char text 0) #\\-)))\n                (subseq text 1)\n                text)))\n        (and (> (length body) 0)\n            (every (lambda (ch) (char<= #\\0 ch #\\9)) body))))\n\n(defun parse-value (text)\n    (let* ((body\n                (if (and (> (length text) 0)\n                        (or (char= (char text 0) #\\+)\n                            (char= (char text 0) #\\-)))\n                    (subseq text 1)\n                    text))\n            (value (parse-integer body)))\n        (if (and (> (length text) 0) (char= (char text 0) #\\-))\n            (- value)\n            value)))\n\n(defun ask-column (board player)\n    (loop\n        (format t \"Player ~a, choose a column (1-7): \" player)\n        (finish-output)\n        (let ((line (read-line *standard-input* nil)))\n            (when (null line)\n                (format t \"~%Input closed. Goodbye.~%\")\n                (return -1))\n            (let ((token (string-trim *space-chars* line)))\n                (cond\n                    ((zerop (length token))\n                        (format t \"~%Invalid input: no column entered.~%\"))\n                    ((not (is-whole-number token))\n                        (format t \"~%Invalid input: \\\"~a\\\" is not a whole number.~%\" token))\n                    (t\n                        (let ((value (parse-value token)))\n                            (cond\n                                ((or (< value 1) (> value *cols*))\n                                    (format t \"~%Invalid input: \\\"~a\\\" is out of range (1-7).~%\"\n                                        token))\n                                ((< (lowest-empty-row board (1- value)) 0)\n                                    (format t \"~%Column ~a is full.~%\" value))\n                                (t\n                                    (return (1- value)))))))))))\n\n(defun play ()\n    (let ((board (make-board))\n            (player-index 0)\n            (moves 0))\n        (format t \"~a~%\" *header*)\n        (format t \"~a~%\" *rules*)\n        (format t \"~%\")\n        (print-board board)\n        (loop\n            (let* ((player (aref *players* player-index))\n                    (column (ask-column board player)))\n                (when (< column 0)\n                    (return))\n                (let ((row (lowest-empty-row board column)))\n                    (setf (aref board row column) player)\n                    (setf moves (1+ moves))\n                    (format t \"~%\")\n                    (print-board board))\n                (when (has-four board player)\n                    (format t \"Player ~a wins!~%\" player)\n                    (finish-output)\n                    (return))\n                (when (= moves (* *rows* *cols*))\n                    (format t \"It's a tie!~%\")\n                    (finish-output)\n                    (return))\n                (setf player-index (- 1 player-index))))))\n\n(play)\n"
