      "code": "{\n    \"title\": \"Connect Four\",\n    \"rows\": 6,\n    \"columns\": 7,\n    \"empty\": \".\",\n    \"players\": [\"X\", \"O\"],\n    \"moves\": [1, 1, 2, 2, 3, 3, 4]\n}\n"
